function useDarkMode() {
  const [dark, setDark] = useState(() => typeof window !== "undefined" && window.matchMedia("(prefers-color-scheme: dark)").matches);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-color-scheme: dark)");
    const h = e => setDark(e.matches);
    mq.addEventListener("change", h);
    return () => mq.removeEventListener("change", h);
  }, []);
  return dark;
}

// ── Reducer ───────────────────────────────────────────────────────────────────
// ── URL routing tabů (záložkovatelné adresy) ─────────────────────────────────
// ?titul=zena | ?titul=ekonom | bez parametru = Aktuálně
function brandFromURL() {
  if (typeof window === "undefined") return "aktualne";
  const p = new URLSearchParams(window.location.search).get("titul");
  return p === "zena" || p === "ekonom" ? p : "aktualne";
}
function brandDefaults(b) {
  if (b === "zena")   return { brandTab:"zena",     bgMode:"templateZena",       fontFamily:"Inter" };
  if (b === "ekonom") return { brandTab:"ekonom",   bgMode:"templateEkonomRich", fontFamily:"Work Sans" };
  return { brandTab:"aktualne", bgMode:"template3", fontFamily:"Inter" };
}
function initialState() {
  return { ...DEFAULTS, ...brandDefaults(brandFromURL()) };
}
function setBrandURL(b) {
  if (typeof window === "undefined") return;
  const url = b === "aktualne" ? window.location.pathname : `${window.location.pathname}?titul=${b}`;
  window.history.replaceState(null, "", url);
}

function reducer(state, action) {
  if (action.type === "RESET") return initialState();
  if (action.type === "SET")   return { ...state, [action.key]: action.value };
  return state;
}

// ── Measurement canvas ────────────────────────────────────────────────────────
const getMeasureCtx = (() => {
  let ctx = null;
  return () => { if (!ctx) ctx = document.createElement("canvas").getContext("2d"); return ctx; };
})();
// Česká typografie: nezlomitelná mezera po jednopísmenných předložkách a spojkách
// (k, s, v, z, o, u, a, i). Dvojí průchod kvůli sousedícím výskytům ("a v Praze").
function czTypo(text) {
  if (!text) return text;
  const re = /([\s(„"']|^)([ksvzouaiKSVZOUAI])[ ]+/g;
  return text.replace(re, "$1$2\u00A0").replace(re, "$1$2\u00A0");
}
function wrapLines(fontStr, text, maxW) {
  const MX = getMeasureCtx(); MX.font = fontStr;
  const words = czTypo(text || "").split(" ").filter(Boolean);
  const lines = []; let line = "";
  for (const word of words) {
    const test = line + word + " ";
    if (MX.measureText(test).width > maxW && line) { lines.push(line.trim()); line = word + " "; }
    else line = test;
  }
  if (line.trim()) lines.push(line.trim());
  return lines;
}
// Vrátí největší zmenšovací faktor (≤1, krok `step`) tak, aby measureFn(fit) ≤ availH.
function fitDownscale(measureFn, availH, minFit = 0.55, step = 0.04) {
  let fit = 1;
  while (fit > minFit) {
    if (measureFn(fit) <= availH) break;
    fit -= step;
  }
  return Math.max(minFit, fit);
}

// ── Draw utilities ────────────────────────────────────────────────────────────
function drawLogoOnCanvas(ctx, cx, cy, r, variant) {
  const circleFill = variant === "black" ? "#111111" : variant === "blue" ? UI : "#ffffff";
  const aFill      = variant === "white" ? "#2B5F9E" : "#ffffff";
  ctx.save();
  ctx.shadowColor = "rgba(0,0,0,0.22)"; ctx.shadowBlur = r * 0.4;
  ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2);
  ctx.fillStyle = circleFill; ctx.fill(); ctx.shadowBlur = 0;
  const fs = r * 1.32;
  ctx.font = `bold ${fs}px Inter, Arial`;
  ctx.textBaseline = "alphabetic"; ctx.textAlign = "center"; ctx.fillStyle = aFill;
  const m = ctx.measureText("A");
  const capH = m.actualBoundingBoxAscent, descH = m.actualBoundingBoxDescent;
  const barW = m.actualBoundingBoxLeft + m.actualBoundingBoxRight;
  const gap = r * 0.10, barH = Math.max(2, r * 0.18);
  const baselineY = cy - (capH + descH + gap + barH) / 2 + capH;
  ctx.fillText("A", cx, baselineY);
  ctx.fillRect(cx - m.actualBoundingBoxLeft, baselineY + descH + gap, barW, barH);
  ctx.restore();
}
function drawLogo(ctx, w, h, variant) {
  const r = w * 0.055;
  drawLogoOnCanvas(ctx, w - w * 0.07 - r, h * 0.055 + r, r, variant);
}
function drawCropped(ctx, img, x, y, w, h, cropRect) {
  if (cropRect) {
    ctx.drawImage(img, cropRect.sx, cropRect.sy, cropRect.srcW, cropRect.srcH, x, y, w, h);
  } else {
    const ir = img.width / img.height, cr = w / h;
    let sx, sy, sw, sh;
    if (ir > cr) { sh = img.height; sw = sh * cr; sx = (img.width - sw) / 2; sy = 0; }
    else         { sw = img.width;  sh = sw / cr; sx = 0; sy = (img.height - sh) / 2; }
    ctx.drawImage(img, sx, sy, sw, sh, x, y, w, h);
  }
}
function drawPhotoPlaceholder(ctx, areaX, areaY, areaW, areaH, cyFrac = 0.5) {
  ctx.fillStyle = "#c8c8c8"; ctx.fillRect(areaX, areaY, areaW, areaH);
  const cx = areaX + areaW / 2, cy = areaY + areaH * cyFrac;
  const ic = Math.min(areaW, areaH) * 0.18;
  ctx.save(); ctx.globalAlpha = 0.7;
  ctx.strokeStyle = "#222"; ctx.fillStyle = "#222";
  ctx.lineWidth = ic * 0.07; ctx.lineCap = "round"; ctx.lineJoin = "round";
  const rw = ic*1.1, rh = ic*0.85, rx = cx-rw/2, ry = cy-rh/2-ic*0.1, rad = ic*0.08;
  ctx.beginPath();
  ctx.moveTo(rx+rad,ry); ctx.lineTo(rx+rw-rad,ry); ctx.arcTo(rx+rw,ry,rx+rw,ry+rad,rad);
  ctx.lineTo(rx+rw,ry+rh-rad); ctx.arcTo(rx+rw,ry+rh,rx+rw-rad,ry+rh,rad);
  ctx.lineTo(rx+rad,ry+rh); ctx.arcTo(rx,ry+rh,rx,ry+rh-rad,rad);
  ctx.lineTo(rx,ry+rad); ctx.arcTo(rx,ry,rx+rad,ry,rad);
  ctx.closePath(); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(cx, ry+rh*0.75); ctx.lineTo(cx, ry+rh*0.25); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(cx-ic*0.18, ry+rh*0.44); ctx.lineTo(cx, ry+rh*0.25); ctx.lineTo(cx+ic*0.18, ry+rh*0.44); ctx.stroke();
  ctx.font = `bold ${areaW * 0.032}px Inter, Arial`;
  ctx.textAlign = "center"; ctx.textBaseline = "alphabetic";
  ctx.fillText("Nahrát fotku", cx, cy + ic * 0.65);
  ctx.restore();
}
function drawPhotoCredit(ctx, w, h, credit, creditColor) {
  if (!credit || !credit.trim()) return;
  const text = `Foto: ${credit.trim()}`;
  const size = Math.round(w * 0.022);
  const pad  = Math.round(w * 0.025);
  ctx.save();
  ctx.font = `${size}px Inter, Arial`;
  ctx.textBaseline = "alphabetic"; ctx.textAlign = "right";
  ctx.globalAlpha = 0.75; ctx.fillStyle = creditColor || "#ffffff";
  ctx.fillText(text, w - pad, h - pad);
  ctx.restore();
}

// ── Žena logo ─────────────────────────────────────────────────────────────────
function drawZenaLogo(ctx, w, h) {
  const img    = _zenaLogoImg();
  const logoW  = w * 0.285;
  const logoH  = logoW * (60 / 138);
  const padX   = w * 0.052;
  const padY   = h * 0.038;
  ctx.save();
  ctx.shadowColor = "rgba(0,0,0,0.55)";
  ctx.shadowBlur  = w * 0.014;
  if (img.complete && img.naturalWidth > 0) {
    ctx.drawImage(img, padX, padY, logoW, logoH);
  }
  ctx.restore();
}

// ── Template draw functions ───────────────────────────────────────────────────
function drawTemplateRich(ctx, w, h, opts) {
  const { bgImage, headline, subtext, supertitle, fontFamily, fontScale,
          logoVariant, richVariant, richPhotoPos, richPanelColor, cropRect, photoCredit } = opts;
  const ff = `${fontFamily}, Arial, sans-serif`;
  const hs = Math.round(w * 0.075 * fontScale * 0.85), ss = Math.round(w * 0.038 * fontScale * 0.85);
  const pad = w * 0.08, maxW = w * 0.84;
  const photoH = Math.round(h * 0.55), panelH = h - photoH;
  const photoY = richPhotoPos === "top" ? 0 : panelH;
  const panelY = richPhotoPos === "top" ? photoH : 0;
  const panelBg = richVariant === "light" ? "#ffffff" : richVariant === "dark" ? "#111111" : richPanelColor;
  ctx.fillStyle = panelBg; ctx.fillRect(0, panelY, w, panelH);
  if (bgImage) drawCropped(ctx, bgImage, 0, photoY, w, photoH, cropRect);
  else drawPhotoPlaceholder(ctx, 0, photoY, w, photoH, 0.5);
  const textCol   = richVariant === "light" ? "#111111" : "#ffffff";
  const accentCol = richVariant === "light" ? UI : richVariant === "color" ? "#ffffff" : "#6AABF0";
  const stSize0 = Math.round(w * 0.034 * fontScale * 0.85);
  const hasSuper = !!(supertitle && supertitle.trim());
  const availH = panelH * 0.80;
  let fit = 1;
  if (subtext) {
    fit = fitDownscale((f) => {
      const hsF = hs*f, ssF = ss*f, stF = stSize0*f;
      const hl = wrapLines(`bold ${hsF}px ${ff}`, headline, maxW);
      const sl = wrapLines(`${ssF}px ${ff}`, subtext, maxW);
      return (hasSuper ? stF*1.7 : 0) + hl.length*hsF*1.28 + ssF*0.9 + sl.length*ssF*1.4;
    }, availH);
  }
  const hsF = hs*fit, ssF = ss*fit, stSize = stSize0*fit;
  const hLines = wrapLines(`bold ${hsF}px ${ff}`, headline, maxW);
  const sLines = subtext ? wrapLines(`${ssF}px ${ff}`, subtext, maxW) : [];
  const blockH = (hasSuper ? stSize * 1.7 : 0) + hLines.length * hsF * 1.28 + (sLines.length ? ssF * 0.9 + sLines.length * ssF * 1.4 : 0);
  let ty = panelY + Math.max(panelH * 0.13, (panelH - blockH) / 2);
  ctx.textAlign = "left"; ctx.textBaseline = "alphabetic";
  if (hasSuper) { ctx.font = `bold ${stSize}px ${ff}`; ctx.fillStyle = accentCol; ctx.fillText(supertitle, pad, ty + stSize * 0.88); ty += stSize * 1.7; }
  ctx.font = `bold ${hsF}px ${ff}`; ctx.fillStyle = textCol;
  hLines.forEach((l, i) => ctx.fillText(l, pad, ty + i * hsF * 1.28 + hsF * 0.88));
  ty += hLines.length * hsF * 1.28;
  if (sLines.length) { ty += ssF * 0.9; ctx.font = `${ssF}px ${ff}`; ctx.globalAlpha = 0.72; sLines.forEach((l, i) => ctx.fillText(l, pad, ty + i * ssF * 1.4 + ssF * 0.88)); ctx.globalAlpha = 1; }
  const creditH = richPhotoPos === "top" ? photoH : h;
  drawPhotoCredit(ctx, w, creditH, photoCredit, opts.creditColor || "#ffffff");
  drawLogo(ctx, w, h, logoVariant);
}
function drawTemplateBlack(ctx, w, h, opts) {
  const { headline, subtext, textColor, fontFamily, fontScale, textPos, logoVariant } = opts;
  const ff = `${fontFamily}, Arial, sans-serif`;
  const hs = Math.round(w * 0.075 * fontScale), ss = Math.round(w * 0.038 * fontScale);
  ctx.fillStyle = "#000"; ctx.fillRect(0, 0, w, h);
  const bx = w*0.07, bw2 = Math.max(4, w*0.007), textX = bx+bw2+w*0.04, tMaxW = w*0.76;
  const topLimit = h*0.08, bottomLimit = h*0.93, availH = bottomLimit - topLimit;
  let fit = 1;
  if (subtext) {
    fit = fitDownscale((f) => {
      const hsF = hs*f, ssF = ss*f;
      const hl = wrapLines(`bold ${hsF}px ${ff}`, headline, tMaxW);
      const sl = wrapLines(`${ssF}px ${ff}`, subtext, tMaxW);
      return hl.length*hsF*1.28 + ssF*0.8 + sl.length*ssF*1.4;
    }, availH);
  }
  const hsF = hs*fit, ssF = ss*fit;
  const lh1 = hsF*1.28, lh2 = ssF*1.4;
  const hLines = wrapLines(`bold ${hsF}px ${ff}`, headline, tMaxW);
  const sLines = subtext ? wrapLines(`${ssF}px ${ff}`, subtext, tMaxW) : [];
  const totalH = hLines.length*lh1 + (sLines.length ? ssF*0.8+sLines.length*lh2 : 0);
  const desiredY = textPos === "top" ? h*0.12 : textPos === "center" ? h*0.38 : h*0.55;
  const yBase = Math.max(topLimit, Math.min(desiredY, bottomLimit - totalH));
  ctx.fillStyle = BAR; ctx.fillRect(bx, yBase-hsF*0.12, bw2, totalH+hsF*0.15);
  ctx.font = `bold ${hsF}px ${ff}`; ctx.fillStyle = textColor;
  ctx.textAlign = "left"; ctx.textBaseline = "alphabetic";
  hLines.forEach((l, i) => ctx.fillText(l, textX, yBase+i*lh1+hsF*0.88));
  if (sLines.length) { ctx.font = `${ssF}px ${ff}`; ctx.globalAlpha = 0.78; const sy2 = yBase+hLines.length*lh1+ssF*1.1; sLines.forEach((l, i) => ctx.fillText(l, textX, sy2+i*lh2)); ctx.globalAlpha = 1; }
  drawLogo(ctx, w, h, logoVariant);
}
function drawTemplateStandard(ctx, w, h, opts) {
  const { bgMode, bgColor, bgImage, overlayOpacity,
          headline, subtext, textColor, fontFamily, fontScale,
          textAlign, textPos, logoVariant, cropRect, photoCredit } = opts;
  const ff = `${fontFamily}, Arial, sans-serif`;
  const hs = Math.round(w * 0.075 * fontScale), ss = Math.round(w * 0.038 * fontScale);
  const pad = w * 0.08, maxW = w * 0.84;
  if (bgMode === "template1") {
    const g = ctx.createLinearGradient(0, 0, 0, h);
    g.addColorStop(0, "#6B9FCC"); g.addColorStop(0.4, "#3A6EA8"); g.addColorStop(1, "#000810");
    ctx.fillStyle = g; ctx.fillRect(0, 0, w, h);
  } else if (bgMode === "image" && bgImage) {
    drawCropped(ctx, bgImage, 0, 0, w, h, cropRect);
    const gy = h * 0.28;
    const og = ctx.createLinearGradient(0, gy, 0, h);
    og.addColorStop(0,    "rgba(0,0,0,0)");
    og.addColorStop(0.38, `rgba(0,0,0,${(overlayOpacity * 0.8).toFixed(2)})`);
    og.addColorStop(1,    `rgba(0,0,0,${overlayOpacity.toFixed(2)})`);
    ctx.fillStyle = og; ctx.fillRect(0, gy, w, h - gy);
  } else if (bgMode === "image") {
    drawPhotoPlaceholder(ctx, 0, 0, w, h, 0.33);
  } else {
    ctx.fillStyle = bgColor; ctx.fillRect(0, 0, w, h);
  }
  const topLimit = h*0.08, bottomLimit = h*0.93, availH = bottomLimit - topLimit;
  let fit = 1;
  if (subtext) {
    fit = fitDownscale((f) => {
      const hsF = hs*f, ssF = ss*f;
      const hl = wrapLines(`bold ${hsF}px ${ff}`, headline, maxW);
      const sl = wrapLines(`${ssF}px ${ff}`, subtext, maxW);
      return hl.length*hsF*1.28 + ssF*0.7 + sl.length*ssF*1.4;
    }, availH);
  }
  const hsF = hs*fit, ssF = ss*fit;
  ctx.fillStyle = textColor; ctx.textBaseline = "alphabetic";
  const hLines = wrapLines(`bold ${hsF}px ${ff}`, headline, maxW);
  const sLines = subtext ? wrapLines(`${ssF}px ${ff}`, subtext, maxW) : [];
  const h1h = hLines.length * hsF * 1.28;
  const totalH = h1h + (sLines.length ? ssF*0.7 + sLines.length*ssF*1.4 : 0);
  const desiredY = textPos === "top" ? h*0.12 : textPos === "center" ? h*0.38 : h*0.55;
  const yBase = Math.max(topLimit, Math.min(desiredY, bottomLimit - totalH));
  const drawLines = (lines, size, lh, y) => {
    lines.forEach((l, i) => { ctx.textAlign = textAlign; const x = textAlign==="center" ? w/2 : textAlign==="right" ? pad+maxW : pad; ctx.fillText(l, x, y+i*lh+size*0.88); });
  };
  ctx.font = `bold ${hsF}px ${ff}`;
  drawLines(hLines, hsF, hsF*1.28, yBase);
  if (sLines.length) { ctx.font = `${ssF}px ${ff}`; ctx.globalAlpha = 0.82; drawLines(sLines, ssF, ssF*1.4, yBase + h1h + ssF*0.7); ctx.globalAlpha = 1; }
  if (bgMode === "image") drawPhotoCredit(ctx, w, h, photoCredit, opts.creditColor || "#ffffff");
  drawLogo(ctx, w, h, logoVariant);
}
function drawTemplateZena(ctx, w, h, opts) {
  const { bgImage, headline, subtext, fontFamily, fontScale, cropRect, photoCredit, zenaOverlay, zenaOverlayOpacity } = opts;
  const op = zenaOverlayOpacity ?? 0.85;
  const ff = `${fontFamily}, Arial, sans-serif`;
  const hs = Math.round(w * 0.065 * fontScale);
  const ss = Math.round(w * 0.034 * fontScale);
  const pad  = w * 0.06;
  const maxW = w * 0.88;

  // 1. Full-bleed photo or placeholder
  if (bgImage) {
    drawCropped(ctx, bgImage, 0, 0, w, h, cropRect);
  } else {
    drawPhotoPlaceholder(ctx, 0, 0, w, h, 0.35);
  }

  // 2. Gradient overlay – tmavý nebo světlý fialový
  const gradY = h * 0.28;
  const g = ctx.createLinearGradient(0, gradY, 0, h);
  if (zenaOverlay === "light") {
    g.addColorStop(0,    `rgba(88, 42, 148, 0)`);
    g.addColorStop(0.38, `rgba(88, 42, 148, ${(op * 0.75).toFixed(2)})`);
    g.addColorStop(1,    `rgba(78, 36, 132, ${op.toFixed(2)})`);
  } else {
    g.addColorStop(0,    `rgba(8, 3, 18, 0)`);
    g.addColorStop(0.38, `rgba(8, 3, 18, ${(op * 0.80).toFixed(2)})`);
    g.addColorStop(1,    `rgba(5, 2, 12, ${op.toFixed(2)})`);
  }
  ctx.fillStyle = g;
  ctx.fillRect(0, gradY, w, h - gradY);

  // 3. Text blok – bottom-up, s auto-fitem
  const botPad   = h * 0.062;
  const topLimit = h * 0.20;                 // spodní hrana loga + rezerva
  const availH   = (h - botPad) - topLimit;
  let fit = 1;
  if (subtext) {
    fit = fitDownscale((f) => {
      const hsF = hs * f, ssF = ss * f;
      const hl = wrapLines(`bold ${hsF}px ${ff}`, headline, maxW);
      const sl = wrapLines(`${ssF}px ${ff}`, subtext, maxW);
      return hl.length * hsF * 1.28 + ssF * 0.85 + sl.length * ssF * 1.4;
    }, availH);
  }
  const hsF = hs * fit, ssF = ss * fit;
  const lh1 = hsF * 1.28;
  const lh2 = ssF * 1.4;
  const hLines = wrapLines(`bold ${hsF}px ${ff}`, headline, maxW);
  const sLines = subtext ? wrapLines(`${ssF}px ${ff}`, subtext, maxW) : [];
  const blockH = hLines.length * lh1 + (sLines.length ? ssF * 0.85 + sLines.length * lh2 : 0);
  let ty = h - botPad - blockH;

  ctx.textAlign    = "left";
  ctx.textBaseline = "alphabetic";

  // Titulek
  ctx.font      = `bold ${hsF}px ${ff}`;
  ctx.fillStyle = "#ffffff";
  ctx.globalAlpha = 1;
  hLines.forEach((l, i) => ctx.fillText(l, pad, ty + i * lh1 + hsF * 0.88));
  ty += hLines.length * lh1;

  // Perex
  if (sLines.length) {
    ty += ssF * 0.85;
    ctx.font = `${ssF}px ${ff}`;
    ctx.globalAlpha = 0.85;
    sLines.forEach((l, i) => ctx.fillText(l, pad, ty + i * lh2 + ssF * 0.88));
    ctx.globalAlpha = 1;
  }

  // 4. Kredit fotografa
  drawPhotoCredit(ctx, w, h, photoCredit, "#ffffff");

  // 5. Logo Žena
  drawZenaLogo(ctx, w, h);
}

// ── Ekonom šablony ────────────────────────────────────────────────────────────
function drawEkonomLogo(ctx, x, y, logoW, variant) {
  const img = variant === "white" ? _ekonomLogoWhite() : _ekonomLogoNavy();
  const logoH = logoW * EKONOM_LOGO_RATIO;
  if (img.complete && img.naturalWidth > 0) ctx.drawImage(img, x, y, logoW, logoH);
  return logoH;
}
// Varianta 1 – foto nahoře (60 %), bílý panel, navy titulek, zelená linka, navy logo
function drawTemplateEkonomRich(ctx, w, h, opts) {
  const { bgImage, headline, subtext, fontFamily, fontScale, cropRect, photoCredit } = opts;
  const ff = `${fontFamily}, Arial, sans-serif`;
  const photoH = Math.round(h * 0.60);
  ctx.fillStyle = "#ffffff"; ctx.fillRect(0, 0, w, h);
  if (bgImage) drawCropped(ctx, bgImage, 0, 0, w, photoH, cropRect);
  else drawPhotoPlaceholder(ctx, 0, 0, w, photoH, 0.5);

  const pad   = w * 0.094, maxW = w * 0.812;
  const hs0   = Math.round(w * 0.051 * fontScale);
  const ss0   = Math.round(w * 0.032 * fontScale);
  const lineW = w * 0.128, lineH = Math.max(3, h * 0.0028);
  const logoW = w * 0.26, logoH = logoW * EKONOM_LOGO_RATIO;
  const botM  = h * 0.055;
  const logoY = h - botM - logoH;
  const lineY = logoY - h * 0.017 - lineH;
  const textTop    = photoH + h * 0.021;
  const availH     = (lineY - h * 0.019) - textTop;

  const fit = fitDownscale((f) => {
    const hsF = hs0 * f, ssF = ss0 * f;
    const hl = wrapLines(`600 ${hsF}px ${ff}`, headline, maxW);
    const sl = subtext ? wrapLines(`${ssF}px ${ff}`, subtext, maxW) : [];
    return hl.length * hsF * 1.32 + (sl.length ? ssF * 0.9 + sl.length * ssF * 1.4 : 0);
  }, availH);
  const hs = hs0 * fit, ss = ss0 * fit;
  const hLines = wrapLines(`600 ${hs}px ${ff}`, headline, maxW);
  const sLines = subtext ? wrapLines(`${ss}px ${ff}`, subtext, maxW) : [];

  ctx.textAlign = "left"; ctx.textBaseline = "alphabetic";
  ctx.font = `600 ${hs}px ${ff}`; ctx.fillStyle = EKONOM;
  let ty = textTop;
  hLines.forEach((l, i) => ctx.fillText(l, pad, ty + i * hs * 1.32 + hs * 0.88));
  ty += hLines.length * hs * 1.32;
  if (sLines.length) {
    ty += ss * 0.9;
    ctx.font = `${ss}px ${ff}`; ctx.globalAlpha = 0.75;
    sLines.forEach((l, i) => ctx.fillText(l, pad, ty + i * ss * 1.4 + ss * 0.88));
    ctx.globalAlpha = 1;
  }
  ctx.fillStyle = EKONOM_GRN; ctx.fillRect(pad, lineY, lineW, lineH);
  drawEkonomLogo(ctx, pad, logoY, logoW, "navy");
  drawPhotoCredit(ctx, w, photoH, photoCredit, "#ffffff");
}
// Varianta 2 – full-bleed foto, navy gradient, bílý titulek, bílá linka, bílé logo
function drawTemplateEkonomFoto(ctx, w, h, opts) {
  const { bgImage, headline, subtext, fontFamily, fontScale, cropRect, photoCredit, ekonomOverlayOpacity } = opts;
  const ff = `${fontFamily}, Arial, sans-serif`;
  const op = ekonomOverlayOpacity ?? 0.9;
  if (bgImage) drawCropped(ctx, bgImage, 0, 0, w, h, cropRect);
  else drawPhotoPlaceholder(ctx, 0, 0, w, h, 0.35);

  const gy = h * 0.55;
  const g = ctx.createLinearGradient(0, gy, 0, h);
  g.addColorStop(0,    `rgba(${EKONOM_NAVY_RGB}, 0)`);
  g.addColorStop(0.45, `rgba(${EKONOM_NAVY_RGB}, ${(op * 0.7).toFixed(2)})`);
  g.addColorStop(1,    `rgba(${EKONOM_NAVY_RGB}, ${op.toFixed(2)})`);
  ctx.fillStyle = g; ctx.fillRect(0, gy, w, h - gy);

  const pad   = w * 0.094, maxW = w * 0.812;
  const hs0   = Math.round(w * 0.048 * fontScale);
  const ss0   = Math.round(w * 0.031 * fontScale);
  const lineW = w * 0.128, lineH = Math.max(3, h * 0.0028);
  const logoW = w * 0.26, logoH = logoW * EKONOM_LOGO_RATIO;
  const botM  = h * 0.055;
  const logoY = h - botM - logoH;
  const lineY = logoY - h * 0.017 - lineH;
  const textBottom = lineY - h * 0.019;
  const availH     = textBottom - h * 0.22;

  const fit = fitDownscale((f) => {
    const hsF = hs0 * f, ssF = ss0 * f;
    const hl = wrapLines(`bold ${hsF}px ${ff}`, headline, maxW);
    const sl = subtext ? wrapLines(`${ssF}px ${ff}`, subtext, maxW) : [];
    return hl.length * hsF * 1.32 + (sl.length ? ssF * 0.9 + sl.length * ssF * 1.4 : 0);
  }, availH);
  const hs = hs0 * fit, ss = ss0 * fit;
  const hLines = wrapLines(`bold ${hs}px ${ff}`, headline, maxW);
  const sLines = subtext ? wrapLines(`${ss}px ${ff}`, subtext, maxW) : [];
  const blockH = hLines.length * hs * 1.32 + (sLines.length ? ss * 0.9 + sLines.length * ss * 1.4 : 0);
  let ty = textBottom - blockH;

  ctx.textAlign = "left"; ctx.textBaseline = "alphabetic";
  ctx.font = `bold ${hs}px ${ff}`; ctx.fillStyle = "#ffffff";
  hLines.forEach((l, i) => ctx.fillText(l, pad, ty + i * hs * 1.32 + hs * 0.88));
  ty += hLines.length * hs * 1.32;
  if (sLines.length) {
    ty += ss * 0.9;
    ctx.font = `${ss}px ${ff}`; ctx.globalAlpha = 0.85;
    sLines.forEach((l, i) => ctx.fillText(l, pad, ty + i * ss * 1.4 + ss * 0.88));
    ctx.globalAlpha = 1;
  }
  ctx.fillStyle = "#ffffff"; ctx.fillRect(pad, lineY, lineW, lineH);
  drawEkonomLogo(ctx, pad, logoY, logoW, "white");
  drawPhotoCredit(ctx, w, h, photoCredit, "#ffffff");
}
function drawPost(ctx, w, h, opts) {
  if (opts.bgMode === "template3")    return drawTemplateRich(ctx, w, h, opts);
  if (opts.bgMode === "template2")    return drawTemplateBlack(ctx, w, h, opts);
  if (opts.bgMode === "templateZena") return drawTemplateZena(ctx, w, h, opts);
  if (opts.bgMode === "templateEkonomRich") return drawTemplateEkonomRich(ctx, w, h, opts);
  if (opts.bgMode === "templateEkonomFoto") return drawTemplateEkonomFoto(ctx, w, h, opts);
  return drawTemplateStandard(ctx, w, h, opts);
}
function renderToCanvas(canvas, fmt, opts, previewMax = PREVIEW_MAX_DESKTOP) {
  const { w, h } = fmt;
  const dpr = Math.min(window.devicePixelRatio || 1, MAX_DPR);
  const s   = Math.min(previewMax / w, previewMax / h);
  canvas.width  = Math.round(w * s * dpr); canvas.height = Math.round(h * s * dpr);
  canvas.style.width  = Math.round(w * s) + "px"; canvas.style.height = Math.round(h * s) + "px";
  const ctx = canvas.getContext("2d");
  ctx.save(); ctx.scale(s * dpr, s * dpr);
  drawPost(ctx, w, h, opts);
  ctx.restore();
}

