function AutoTextarea({ value, onChange, onFocus, placeholder, minHeight, t, mobile }) {
  const ref = useRef(null);
  useLayoutEffect(() => {
    const el = ref.current; if (!el) return;
    el.style.height = "auto";
    el.style.height = Math.max(minHeight, el.scrollHeight) + "px";
  }, [value, minHeight, mobile]);
  return (
    <textarea ref={ref} value={value} onChange={onChange} onFocus={onFocus} placeholder={placeholder}
      style={{ ...mkInp(t, mobile), minHeight, resize:"none", overflow:"hidden" }} />
  );
}

function ArticleLoader({ onLoad, t, mobile, source = "aktualne", accent: accentProp, hoverBg: hoverBgProp }) {
  const accent  = accentProp || UI;
  const hoverBg = hoverBgProp || t.advActiveBg;
  const hint    = source === "zena" ? "https://zena.aktualne.cz/…" : source === "ekonom" ? "https://ekonom.cz/…" : "https://zpravy.aktualne.cz/…";
  const [url, setUrl]         = useState("");
  const [loading, setLoading] = useState(false);
  const [msg, setMsg]         = useState(null); // { type:"err"|"ok", text }
  const [feedOpen, setFeedOpen]       = useState(false);
  const [feedLoading, setFeedLoading] = useState(false); // úvodní načtení (spinner přes celý seznam)
  const [feedMore, setFeedMore]       = useState(false); // probíhá "Načíst další"
  const [feedItems, setFeedItems]     = useState([]);
  const [feedErr, setFeedErr]         = useState(null);
  const [feedPage, setFeedPage]       = useState(0);
  const [feedHasMore, setFeedHasMore] = useState(false);
  const [hoveredIdx, setHoveredIdx]   = useState(-1);

  const run = async (v) => {
    const target = (v != null ? v : url).trim();
    if (!target || loading) return;
    setUrl(target);
    setLoading(true); setMsg(null);
    const r = await onLoad(target);
    setLoading(false);
    if (!r.ok) setMsg({ type:"err", text: r.error || "Načtení selhalo." });
    else setMsg({ type:"ok", text: r.noImage ? "Načteno (článek bez hlavní fotky)." : "Článek načten." });
  };

  const fetchFeedPage = async (page, append) => {
    try {
      const resp = await fetch(`/api/fetch-feed?page=${page}${source !== "aktualne" ? `&source=${source}` : ""}`);
      const data = await resp.json().catch(() => ({}));
      if (!resp.ok) { setFeedErr(data.error || `Chyba ${resp.status}.`); return; }
      setFeedErr(null);
      setFeedItems(prev => append ? [...prev, ...(data.items || [])] : (data.items || []));
      setFeedPage(page);
      setFeedHasMore(!!data.hasMore);
    } catch {
      setFeedErr("Feed se nepodařilo načíst.");
    }
  };

  // Feed se načítá automaticky při zobrazení (krok 1 workflow)
  useEffect(() => {
    let cancelled = false;
    (async () => {
      setFeedLoading(true);
      await fetchFeedPage(1, false);
      if (!cancelled) setFeedLoading(false);
    })();
    return () => { cancelled = true; };
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  const loadMore = async () => {
    if (feedMore) return;
    setFeedMore(true);
    await fetchFeedPage(feedPage + 1, true);
    setFeedMore(false);
  };

  const pick = (link) => { setFeedOpen(false); setMsg(null); run(link); };
  const selectInput = e => { const el = e.target; setTimeout(() => el.select(), 0); };

  // Globální Ctrl+V: vložení URL ze schránky kdekoli v aplikaci načte článek,
  // i bez kliknutí do pole. Stačí mít URL aktualne.cz ve schránce.
  const runRef = useRef(run);
  runRef.current = run;
  useEffect(() => {
    const onDocPaste = (e) => {
      const txt = (e.clipboardData && e.clipboardData.getData("text") || "").trim();
      if (/(aktualne|ekonom)\.cz\//i.test(txt)) { e.preventDefault(); runRef.current(txt); }
    };
    document.addEventListener("paste", onDocPaste);
    return () => document.removeEventListener("paste", onDocPaste);
  }, []);

  // Článek je "aktualizovaný", pokud má starší čas vydání než kterýkoli článek pod ním
  // (feed je řazen podle času aktualizace → taková inverze znamená posun nahoru kvůli update).
  const updatedFlags = (() => {
    const flags = new Array(feedItems.length).fill(false);
    let maxBelow = -Infinity;
    for (let i = feedItems.length - 1; i >= 0; i--) {
      const ts = feedItems[i].ts || 0;
      if (ts < maxBelow) flags[i] = true;
      if (ts > maxBelow) maxBelow = ts;
    }
    return flags;
  })();

  return (
    <div style={mkCard(t)}>
      <div style={{ fontSize:10, fontWeight:700, color:t.textMuted, textTransform:"uppercase", letterSpacing:"0.05em", marginBottom:6 }}>1 · Článek</div>
      <input type="url" value={url} onChange={e => setUrl(e.target.value)}
        onFocus={selectInput}
        onKeyDown={e => { if (e.key === "Enter") run(); }}
        placeholder={hint}
        style={mkInp(t, mobile)} />
      <button onClick={() => run()} disabled={loading}
        style={{ ...mkBtn(true, accent, t), width:"100%", marginTop:6, padding:"8px 0", opacity: loading ? 0.6 : 1, cursor: loading ? "default" : "pointer" }}>
        {loading ? "Načítám…" : "Načíst článek"}
      </button>
      {msg && <div style={{ fontSize:11, color: msg.type === "err" ? "#d9534f" : t.textMuted, marginTop:6, lineHeight:1.4 }}>{msg.text}</div>}

      <div style={{ ...mkLbl(t), marginTop:10, marginBottom:4 }}>Nejnovější články</div>
      <div style={{ maxHeight: feedOpen ? 320 : "none", overflowY: feedOpen ? "auto" : "visible", border:`1px solid ${t.borderLight}`, borderRadius:6 }}>
          {feedLoading && <div style={{ fontSize:11, color:t.textMuted, padding:"8px 10px" }}>Načítám feed…</div>}
          {feedErr && <div style={{ fontSize:11, color:"#d9534f", padding:"8px 10px" }}>{feedErr}</div>}
          {!feedLoading && !feedErr && (feedOpen ? feedItems : feedItems.slice(0, 3)).map((it, i) => (
            <button key={i} onClick={() => pick(it.link)}
              onMouseEnter={() => setHoveredIdx(i)} onMouseLeave={() => setHoveredIdx(-1)}
              style={{ display:"block", width:"100%", textAlign:"left", border:"none", borderBottom: i < feedItems.length - 1 ? `1px solid ${t.borderLight}` : "none", cursor:"pointer", fontSize:13, lineHeight:1.35, padding:"8px 10px", transition:"background .15s, color .15s", background: hoveredIdx === i ? hoverBg : "transparent", color: hoveredIdx === i ? accent : t.textPrimary }}>
              {it.time && (
                <span style={{ display:"inline-flex", alignItems:"center", fontWeight:700, color: hoveredIdx === i ? accent : t.textMuted, marginRight:6, whiteSpace:"nowrap" }}>
                  {it.time}
                  {updatedFlags[i] && <span title="Aktualizováno" style={{ width:6, height:6, borderRadius:"50%", background:"#E8821E", marginLeft:4, flexShrink:0 }} />}
                </span>
              )}
              {it.title}
            </button>
          ))}
          {!feedLoading && !feedErr && feedItems.length === 0 && <div style={{ fontSize:11, color:t.textMuted, padding:"8px 10px" }}>Žádné články.</div>}
          {!feedLoading && !feedErr && feedItems.length > 3 && (
            <button onClick={() => setFeedOpen(!feedOpen)}
              style={{ display:"block", width:"100%", textAlign:"center", border:"none", borderTop:`1px solid ${t.borderLight}`, background:"transparent", color:accent, cursor:"pointer", fontSize:11, fontWeight:600, padding:"8px 10px" }}>
              {feedOpen ? "▲ Zobrazit méně" : `▼ Další články (${feedItems.length - 3}${feedHasMore ? "+" : ""})`}
            </button>
          )}
          {!feedLoading && !feedErr && feedOpen && feedHasMore && (
            <button onClick={loadMore} disabled={feedMore}
              style={{ display:"block", width:"100%", textAlign:"center", border:"none", borderTop:`1px solid ${t.borderLight}`, background:"transparent", color:accent, cursor: feedMore ? "default" : "pointer", fontSize:11, fontWeight:600, padding:"9px 10px", opacity: feedMore ? 0.6 : 1 }}>
              {feedMore ? "Načítám…" : "Načíst další"}
            </button>
          )}
        </div>
    </div>
  );
}

function EkonomRichControls({ onImageUpload, t }) {
  return (
    <div style={mkCard(t)}>
      <label style={mkUpload(t)}>📁 Nahrát fotku<input type="file" accept="image/*" onChange={e => onImageUpload(e, "templateEkonomRich")} style={{ display:"none" }} /></label>
    </div>
  );
}

function EkonomFotoControls({ st, dispatch, onImageUpload, t }) {
  const set = (key, val) => dispatch({ type:"SET", key, value:val });
  return (
    <div style={mkCard(t)}>
      <label style={mkUpload(t)}>📁 Nahrát fotku<input type="file" accept="image/*" onChange={e => onImageUpload(e, "templateEkonomFoto")} style={{ display:"none" }} /></label>
      <div style={mkLbl(t)}>Intenzita překryvu</div>
      <input type="range" min="0" max="1" step="0.05" value={st.ekonomOverlayOpacity} onChange={e => set("ekonomOverlayOpacity", parseFloat(e.target.value))} style={{ width:"100%", accentColor: ekonomAccent(t) }} />
      <span style={{ fontSize:11, color:t.textMuted }}>{Math.round(st.ekonomOverlayOpacity * 100)} %</span>
    </div>
  );
}

function Controls({ st, dispatch, onImageUpload, onLoadArticle, autoResize, selectAll, t, mobile }) {
  const set = (key, val) => dispatch({ type:"SET", key, value:val });
  const B   = active => mkBtn(active, UI, t);
  const isEkonomTpl = st.bgMode === "templateEkonomRich" || st.bgMode === "templateEkonomFoto";
  const brand  = st.brandTab || (st.bgMode === "templateZena" ? "zena" : isEkonomTpl ? "ekonom" : "aktualne");
  const accent = brand === "zena" ? ZENA : brand === "ekonom" ? ekonomAccent(t) : UI;
  const [editOpen, setEditOpen] = useState(false);
  const switchBrand = (b) => {
    setBrandURL(b);
    set("brandTab", b);
    set("fontFamily", b === "ekonom" ? "Work Sans" : "Inter");
    if (b === "aktualne") { set("bgMode","template3"); set("richPhotoPos","top"); set("richVariant","dark"); set("logoVariant","blue"); }
    else if (b === "zena")   set("bgMode","templateZena");
    else if (b === "ekonom") set("bgMode","templateEkonomRich");
  };
  const [perexCopied, setPerexCopied] = useState(false);
  const copyPerex = async () => {
    const perex = (st.subtext || "").trim();
    if (!perex || !navigator.clipboard) return;
    try {
      await navigator.clipboard.writeText(perex);
      setPerexCopied(true);
      setTimeout(() => setPerexCopied(false), 1400);
    } catch { /* ignore */ }
  };
  const isPhotoMode = st.bgMode === "template3" || (st.bgMode === "custom" && st.customSub === "image") || st.bgMode === "templateZena" || isEkonomTpl;
  return (
    <>
      <ArticleLoader key={brand} source={brand} onLoad={onLoadArticle} t={t} mobile={mobile}
        accent={accent} hoverBg={brand === "zena" ? "rgba(123,63,175,0.12)" : brand === "ekonom" ? (t.isDark ? "rgba(124,143,217,0.20)" : "rgba(41,48,90,0.12)") : t.advActiveBg} />
      <div style={{ ...mkLbl(t), marginTop:12 }}>Titul</div>
      <div style={{ display:"flex", gap:6, marginBottom:8 }}>
        {[["aktualne","Aktuálně"],["zena","Žena"],["ekonom","Ekonom"]].map(([b, lab]) => {
          const bCol = b === "zena" ? ZENA : b === "ekonom" ? ekonomAccent(t) : UI;
          return (
            <button key={b} onClick={() => switchBrand(b)} style={{ ...mkBtn(brand === b, bCol, t), flex:1, fontSize:12, padding:"7px 0" }}>{lab}</button>
          );
        })}
      </div>
      <button onClick={() => setEditOpen(!editOpen)} style={{ width:"100%", marginTop:2, padding:"9px 10px", borderRadius:7, border:`1px solid ${editOpen ? accent : t.border}`, background: editOpen ? (t.isDark ? "rgba(255,255,255,0.04)" : t.advActiveBg) : t.bgAdvanced, cursor:"pointer", display:"flex", justifyContent:"space-between", alignItems:"center", fontSize:12, fontWeight:600, color: editOpen ? accent : t.textSecondary }}>
        <span>✏️ Upravit post (formát, texty, šablony)</span>
        <span style={{ fontSize:10, display:"inline-block", transform: editOpen ? "rotate(180deg)" : "none", transition:"transform .2s" }}>▼</span>
      </button>
      {editOpen && (<>
      <div style={mkLbl(t)}>Formát</div>
      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:6 }}>
        {FORMATS.map(f => (
          <button key={f.id} onClick={() => { set("fmt", f); set("cropRect", null); }} style={{ ...mkBtn(st.fmt.id===f.id, accent, t), display:"flex", flexDirection:"column", alignItems:"center", gap:1, padding:"7px 4px" }}>
            <span style={{ fontSize:11 }}>{f.label}</span>
            <span style={{ fontSize:10, opacity:0.7 }}>{f.sub}</span>
          </button>
        ))}
      </div>
      {st.bgMode === "template3" && (
        <>
          <label style={mkLbl(t)}>Nadtitulek</label>
          <textarea value={st.supertitle} onChange={e => { set("supertitle", e.target.value); autoResize(e); }} onFocus={selectAll} placeholder="Volitelný nadtitulek…" style={{ ...mkInp(t, mobile), height:36, resize:"none", overflow:"hidden" }} />
        </>
      )}
      <label style={mkLbl(t)}>Titulek</label>
      <AutoTextarea value={st.headline} onChange={e => set("headline", e.target.value)} onFocus={selectAll} minHeight={44} t={t} mobile={mobile} />
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginTop:12, marginBottom:4 }}>
        <label style={{ ...mkLbl(t), display:"flex", alignItems:"center", gap:6, margin:0 }}>
          <input type="checkbox" checked={st.showPerex} onChange={e => set("showPerex", e.target.checked)} style={{ margin:0, cursor:"pointer" }} />
          <span>Perex</span>
          <span style={{ fontWeight:400, textTransform:"none", letterSpacing:0, color:t.textMuted }}>{st.showPerex ? "(zobrazit)" : "(skryto)"}</span>
        </label>
        <button onClick={copyPerex} disabled={!(st.subtext || "").trim()} title="Kopírovat perex do schránky"
          style={{ display:"flex", alignItems:"center", gap:4, background:"none", border:"none", padding:"2px 4px", cursor: (st.subtext || "").trim() ? "pointer" : "default", color: perexCopied ? "#2e9e5b" : ((st.subtext || "").trim() ? accent : t.textFaint) }}>
          {perexCopied ? (
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12" /></svg>
          ) : (
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect x="9" y="9" width="11" height="11" rx="2" /><path d="M5 15V5a2 2 0 0 1 2-2h10" /></svg>
          )}
          <span style={{ fontSize:10, fontWeight:600 }}>{perexCopied ? "Zkopírováno" : "Kopírovat"}</span>
        </button>
      </div>
      <AutoTextarea value={st.subtext} onChange={e => set("subtext", e.target.value)} onFocus={selectAll} placeholder="Volitelný perex…" minHeight={52} t={t} mobile={mobile} />
      {isPhotoMode && (
        <>
          <label style={mkLbl(t)}>Kredit fotografa</label>
          <input type="text" value={st.photoCredit} onChange={e => set("photoCredit", e.target.value)} placeholder="Jméno / agentura…" style={mkInp(t, mobile)} />
        </>
      )}
      <div style={mkLbl(t)}>Pozadí / šablona</div>
      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:6, marginBottom:6 }}>
        {brand === "aktualne" && <>
        <button onClick={() => { set("bgMode","template2"); set("logoVariant","blue"); set("fontFamily","Inter"); }} style={tplBtn(st.bgMode,"template2",t)}>
          <span style={{ width:48, height:28, borderRadius:3, background:"#000", border:"2px solid #1B69BF", display:"block" }} /><span style={{ fontSize:10 }}>Černá</span>
        </button>
        <button onClick={() => { set("bgMode","template1"); set("logoVariant","blue"); set("fontFamily","Inter"); }} style={tplBtn(st.bgMode,"template1",t)}>
          <span style={{ width:48, height:28, borderRadius:3, background:"linear-gradient(to bottom,#6B9FCC,#000810)", display:"block" }} /><span style={{ fontSize:10 }}>Modrá</span>
        </button>
        <button onClick={() => { set("bgMode","template3"); set("logoVariant","white"); set("fontFamily","Inter"); }} style={tplBtn(st.bgMode,"template3",t)}>
          <span style={{ width:48, height:28, borderRadius:3, overflow:"hidden", display:"flex", flexDirection:"column" }}>
            <span style={{ flex:"0 0 55%", background:"#aaa" }} /><span style={{ flex:"0 0 45%", background:"#1B69BF" }} />
          </span><span style={{ fontSize:10 }}>Rich</span>
        </button>
        <button onClick={() => { set("bgMode","custom"); set("customSub","image"); set("logoVariant","blue"); set("fontFamily","Inter"); }} style={tplBtn(st.bgMode,"custom",t)}>
          <span style={{ width:48, height:28, borderRadius:3, background:"conic-gradient(red,yellow,lime,cyan,blue,magenta,red)", display:"block" }} /><span style={{ fontSize:10 }}>Vlastní</span>
        </button>
        </>}
        {brand === "zena" && <>
        <button onClick={() => { set("bgMode","templateZena"); set("fontFamily","Inter"); }} style={tplBtn(st.bgMode,"templateZena",t)}>
          <span style={{ width:48, height:28, borderRadius:3, position:"relative", overflow:"hidden", display:"block", background:"#888" }}>
            <span style={{ position:"absolute", bottom:0, left:0, right:0, height:"65%", background:"linear-gradient(to bottom, transparent, rgba(78,35,130,0.92))" }} />
            <img src={ZENA_LOGO_B64} alt="Žena" style={{ position:"absolute", top:"50%", left:"50%", transform:"translate(-50%,-50%)", width:"80%", height:"auto", display:"block" }} />
          </span>
          <span style={{ fontSize:10 }}>Žena.cz</span>
        </button>
        </>}
        {brand === "ekonom" && <>
        <button onClick={() => { set("bgMode","templateEkonomRich"); set("fontFamily","Work Sans"); }} style={tplBtn(st.bgMode,"templateEkonomRich",t)}>
          <span style={{ width:48, height:28, borderRadius:3, overflow:"hidden", display:"flex", flexDirection:"column", background:"#fff" }}>
            <span style={{ flex:"0 0 55%", background:"#aaa" }} />
            <span style={{ flex:"1", display:"flex", alignItems:"center", paddingLeft:4 }}>
              <img src={EKONOM_LOGO_NAVY_B64} alt="ekonom" style={{ width:"55%", height:"auto", display:"block" }} />
            </span>
          </span>
          <span style={{ fontSize:10 }}>Ekonom</span>
        </button>
        <button onClick={() => { set("bgMode","templateEkonomFoto"); set("fontFamily","Work Sans"); }} style={tplBtn(st.bgMode,"templateEkonomFoto",t)}>
          <span style={{ width:48, height:28, borderRadius:3, position:"relative", overflow:"hidden", display:"block", background:"#888" }}>
            <span style={{ position:"absolute", bottom:0, left:0, right:0, height:"70%", background:"linear-gradient(to bottom, transparent, rgba(39,49,98,0.95))" }} />
            <img src={EKONOM_LOGO_WHITE_B64} alt="ekonom" style={{ position:"absolute", bottom:3, left:4, width:"55%", height:"auto", display:"block" }} />
          </span>
          <span style={{ fontSize:10 }}>Ekonom foto</span>
        </button>
        </>}
      </div>
      {st.bgMode === "template3"    && <RichControls   st={st} dispatch={dispatch} onImageUpload={onImageUpload} t={t} mobile={mobile} />}
      {st.bgMode === "custom"       && <CustomControls st={st} dispatch={dispatch} onImageUpload={onImageUpload} t={t} mobile={mobile} />}
      {st.bgMode === "templateZena" && <ZenaControls   st={st} dispatch={dispatch} onImageUpload={onImageUpload} t={t} />}
      {st.bgMode === "templateEkonomRich" && <EkonomRichControls onImageUpload={onImageUpload} t={t} />}
      {st.bgMode === "templateEkonomFoto" && <EkonomFotoControls st={st} dispatch={dispatch} onImageUpload={onImageUpload} t={t} />}
      <AdvancedSettings st={st} dispatch={dispatch} t={t} mobile={mobile} />
      </>)}
    </>
  );
}

function Preview({ canvasRef, fmt, t, onImageUpload, onOpenCrop, bgMode, customSub, hasImage }) {
  const fileInputRef = useRef(null);
  const [hovered, setHovered] = useState(false);
  const PHOTO_TPLS = ["template3", "templateZena", "templateEkonomRich", "templateEkonomFoto"];
  const isPhotoMode = PHOTO_TPLS.includes(bgMode) || (bgMode === "custom" && customSub === "image");
  const uploadTarget = PHOTO_TPLS.includes(bgMode) ? bgMode : null;
  return (
    <div style={{ display:"flex", flexDirection:"column", alignItems:"center" }}>
      <div style={{ textAlign:"center", fontSize:11, color:t.textMuted, marginBottom:10, fontWeight:600, textTransform:"uppercase", letterSpacing:"0.08em" }}>
        Náhled — {fmt.label} ({fmt.w} × {fmt.h})
      </div>
      <div style={{ position:"relative", display:"inline-block" }} onMouseEnter={() => isPhotoMode && setHovered(true)} onMouseLeave={() => setHovered(false)}>
        <canvas ref={canvasRef} style={{ borderRadius:10, boxShadow:"0 6px 28px rgba(0,0,0,0.25)", display:"block", maxWidth:"100%" }} />
        {isPhotoMode && (
          <>
            <div onClick={() => fileInputRef.current?.click()} style={{ position:"absolute", inset:0, borderRadius:10, background:"transparent", cursor:"pointer" }} />
            {hovered && (
              <div style={{ position:"absolute", bottom:12, left:"50%", transform:"translateX(-50%)", background:"rgba(0,0,0,0.72)", color:"#fff", fontSize:12, fontWeight:600, padding:"6px 14px", borderRadius:20, whiteSpace:"nowrap", pointerEvents:"none" }}>
                📁 Klikni pro nahrání fotky
              </div>
            )}
            <input ref={fileInputRef} type="file" accept="image/*" style={{ display:"none" }} onChange={e => onImageUpload(e, uploadTarget)} />
          </>
        )}
      </div>
      {isPhotoMode && hasImage && (
        <button onClick={onOpenCrop} style={{ ...mkBtn(false, UI, t), marginTop:10, padding:"7px 18px", fontSize:12 }}>✂️ Upravit výřez</button>
      )}
    </div>
  );
}

function Actions({ fmt, onReset, onExport, onExportAll, onCopy, onShorten, onNewPost, articleUrl, perex, mobile, t, accent = UI }) {
  const pad = `${mobile ? 12 : 10}px 0`, fz = mobile ? 14 : 13;
  const [copied, setCopied]     = useState(null); // null | "ok" | "err"
  const [allBusy, setAllBusy]   = useState(false);
  const [share, setShare]       = useState(null); // { forUrl, status:"loading"|"ok"|"err", shortlink?, error? }
  const [shareCopied, setShareCopied] = useState(false);

  const handleCopy = async () => {
    const ok = await onCopy();
    setCopied(ok ? "ok" : "err");
    setTimeout(() => setCopied(null), 1800);
    // Po zkopírování fotky připrav sdílecí text: zkrácený odkaz + perex
    if (articleUrl) {
      setShare({ forUrl: articleUrl, status: "loading" });
      const r = await onShorten();
      setShare(r.ok
        ? { forUrl: articleUrl, status: "ok",  shortlink: r.shortlink }
        : { forUrl: articleUrl, status: "err", error: r.error });
    }
  };
  const handleAll = () => {
    if (allBusy) return;
    setAllBusy(true);
    onExportAll();
    setTimeout(() => setAllBusy(false), 1600);
  };
  // Text sdílecího pole: 👉 zkrácený odkaz + perex (fallback na plnou URL při chybě zkracovače)
  const shareLink = share && (share.status === "ok" ? share.shortlink : share.status === "err" ? share.forUrl : null);
  const shareText = shareLink ? `👉 ${shareLink}${(perex || "").trim() ? " " + perex.trim() : ""}` : "";
  const showShare = share && share.forUrl === articleUrl; // skryj po resetu / načtení jiného článku
  const copyShare = async () => {
    if (!shareText || !navigator.clipboard) return;
    try {
      await navigator.clipboard.writeText(shareText);
      setShareCopied(true);
      setTimeout(() => setShareCopied(false), 1400);
    } catch { /* ignore */ }
  };

  return (
    <div style={{ display:"flex", flexDirection:"column", gap:8, ...(!mobile && { marginTop:16, paddingTop:14, borderTop:`1px solid ${t.borderLight}` }) }}>
      <button onClick={onReset}  style={{ ...mkBtn(false, UI, t), width:"100%", fontSize:fz, padding:pad }}>Začít znovu</button>
      <button onClick={handleCopy} style={{ ...mkBtn(true, accent, t), width:"100%", fontSize:fz, padding:pad }}>
        {copied === "ok" ? "Obrázek zkopírován ✓" : copied === "err" ? "Nepodporováno" : "2 · Kopírovat obrázek"}
      </button>
      {showShare && (
        <div style={{ border:`1px solid ${t.borderLight}`, borderRadius:7, padding:"8px 10px", background:t.bgAdvanced }}>
          <div style={{ fontSize:10, fontWeight:700, color:t.textMuted, textTransform:"uppercase", letterSpacing:"0.05em", marginBottom:4 }}>3 · Text postu</div>
          {share.status === "loading" && <div style={{ fontSize:11, color:t.textMuted }}>Zkracuji odkaz…</div>}
          {share.status !== "loading" && (
            <>
              <div style={{ fontSize:12, color:t.textPrimary, lineHeight:1.45, wordBreak:"break-word", whiteSpace:"pre-wrap" }}>{shareText}</div>
              {share.status === "err" && <div style={{ fontSize:10, color:"#d9534f", marginTop:4 }}>Zkrácení selhalo ({share.error}) – použita plná adresa.</div>}
              <button onClick={copyShare} style={{ display:"flex", alignItems:"center", gap:4, background:"none", border:"none", padding:"4px 0 0", cursor:"pointer", color: shareCopied ? "#2e9e5b" : accent }}>
                {shareCopied ? (
                  <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12" /></svg>
                ) : (
                  <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect x="9" y="9" width="11" height="11" rx="2" /><path d="M5 15V5a2 2 0 0 1 2-2h10" /></svg>
                )}
                <span style={{ fontSize:11, fontWeight:600 }}>{shareCopied ? "Zkopírováno" : "Kopírovat text"}</span>
              </button>
              {shareCopied && (
                <button onClick={onNewPost} style={{ ...mkBtn(true, accent, t), width:"100%", marginTop:8, padding:"8px 0", fontSize:12 }}>
                  ✓ Hotovo — začít nový post
                </button>
              )}
            </>
          )}
        </div>
      )}
      <div style={{ display:"flex", gap:8 }}>
        <button onClick={onExport} style={{ ...mkBtn(false, accent, t), flex:1, fontSize:12, padding:"8px 0" }}>⬇ Stáhnout</button>
        <button onClick={handleAll} disabled={allBusy} style={{ ...mkBtn(false, accent, t), flex:1, fontSize:12, padding:"8px 0", opacity: allBusy ? 0.6 : 1 }}>
          {allBusy ? "Stahuji…" : "⬇ Všechny formáty"}
        </button>
      </div>
      <div style={{ fontSize:10, color:t.textFaint, textAlign:"center" }}>{fmt.w} × {fmt.h} px</div>
    </div>
  );
}

function AppHeader({ logoCanvasRef, onLogoClick, t }) {
  return (
    <div onClick={onLogoClick} style={{ fontSize:15, fontWeight:700, color:UI, display:"flex", alignItems:"center", gap:8, cursor:"pointer", userSelect:"none" }}>
      <canvas ref={logoCanvasRef} style={{ width:28, height:28, flexShrink:0 }} />
      Post Generator
    </div>
  );
}

// ── Crop Modal ────────────────────────────────────────────────────────────────
function CropModal({ img, cropW, cropH, initialCrop, onConfirm, onCancel }) {
  const MAX_PV     = Math.min(460, window.innerWidth - 32, window.innerHeight - 220);
  const pvScale    = Math.min(MAX_PV / cropW, MAX_PV / cropH);
  const pw         = Math.round(cropW * pvScale);
  const ph         = Math.round(cropH * pvScale);
  const coverScale = Math.max(pw / img.width, ph / img.height);

  const initCrop = () => {
    if (initialCrop) {
      const z  = pw / (initialCrop.srcW * coverScale);
      const ds = coverScale * z;
      const cx = initialCrop.sx + initialCrop.srcW / 2;
      const cy = initialCrop.sy + initialCrop.srcH / 2;
      return { zoom: z, panX: (cx - img.width / 2) * ds, panY: (cy - img.height / 2) * ds };
    }
    return { zoom: 1, panX: 0, panY: 0 };
  };

  const cropReducer = (s, a) => {
    if (a.type === "PAN")  return { ...s, panX: s.panX + a.dx, panY: s.panY + a.dy };
    if (a.type === "ZOOM") { const nz = Math.max(1, Math.min(5, s.zoom * a.delta)), ratio = nz / s.zoom; return { zoom: nz, panX: s.panX * ratio, panY: s.panY * ratio }; }
    return s;
  };

  const [crop, dispatchCrop] = useReducer(cropReducer, null, initCrop);
  const dragging      = useRef(false);
  const lastPos       = useRef({ x:0, y:0 });
  const lastPinchDist = useRef(null);
  const containerRef  = useRef(null);
  const pvCanvasRef   = useRef(null);

  const ds      = coverScale * crop.zoom;
  const maxPX   = Math.max(0, (img.width  * ds - pw) / 2);
  const maxPY   = Math.max(0, (img.height * ds - ph) / 2);
  const cpx     = Math.max(-maxPX, Math.min(maxPX, crop.panX));
  const cpy     = Math.max(-maxPY, Math.min(maxPY, crop.panY));
  const scaledW = img.width  * ds;
  const scaledH = img.height * ds;

  useEffect(() => {
    const el = containerRef.current; if (!el) return;
    const onWheel = e => { e.preventDefault(); e.stopPropagation(); dispatchCrop({ type:"ZOOM", delta: e.deltaY > 0 ? 0.92 : 1.08 }); };
    el.addEventListener("wheel", onWheel, { passive: false });
    return () => el.removeEventListener("wheel", onWheel);
  }, []);

  useEffect(() => {
    const c = pvCanvasRef.current; if (!c) return;
    c.width = pw; c.height = ph;
    const ctx = c.getContext("2d");
    ctx.clearRect(0, 0, pw, ph);
    ctx.drawImage(img, 0, 0, img.width, img.height, pw/2 - cpx - scaledW/2, ph/2 - cpy - scaledH/2, scaledW, scaledH);
  }, [cpx, cpy, scaledW, scaledH, pw, ph, img]);

  const onMouseDown = e => { dragging.current = true; lastPos.current = { x:e.clientX, y:e.clientY }; e.preventDefault(); };
  const onMouseMove = e => {
    if (!dragging.current) return;
    dispatchCrop({ type:"PAN", dx: -(e.clientX - lastPos.current.x), dy: -(e.clientY - lastPos.current.y) });
    lastPos.current = { x:e.clientX, y:e.clientY };
  };
  const onMouseUp = () => { dragging.current = false; };
  const onTouchStart = e => {
    if (e.touches.length === 1) lastPos.current = { x:e.touches[0].clientX, y:e.touches[0].clientY };
    else if (e.touches.length === 2) lastPinchDist.current = Math.hypot(e.touches[0].clientX - e.touches[1].clientX, e.touches[0].clientY - e.touches[1].clientY);
    e.preventDefault();
  };
  const onTouchMove = e => {
    if (e.touches.length === 1) {
      dispatchCrop({ type:"PAN", dx: -(e.touches[0].clientX - lastPos.current.x), dy: -(e.touches[0].clientY - lastPos.current.y) });
      lastPos.current = { x:e.touches[0].clientX, y:e.touches[0].clientY };
    } else if (e.touches.length === 2 && lastPinchDist.current) {
      const dist = Math.hypot(e.touches[0].clientX - e.touches[1].clientX, e.touches[0].clientY - e.touches[1].clientY);
      dispatchCrop({ type:"ZOOM", delta: dist / lastPinchDist.current });
      lastPinchDist.current = dist;
    }
    e.preventDefault();
  };

  const handleConfirm = () => {
    const cx = img.width / 2 + cpx / ds, cy = img.height / 2 + cpy / ds;
    const srcW = pw / ds, srcH = ph / ds;
    onConfirm({ sx: Math.max(0, Math.min(img.width - srcW, cx - srcW/2)), sy: Math.max(0, Math.min(img.height - srcH, cy - srcH/2)), srcW: Math.min(srcW, img.width), srcH: Math.min(srcH, img.height) });
  };

  return (
    <div style={{ position:"fixed", inset:0, background:"rgba(0,0,0,0.88)", display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", zIndex:2000, gap:14, padding:16 }}>
      <div style={{ color:"#fff", fontSize:14, fontWeight:600 }}>Upravit výřez</div>
      <div style={{ color:"rgba(255,255,255,0.5)", fontSize:12, marginTop:-8 }}>Táhni pro posun · scroll / pinch pro přiblížení</div>
      <div ref={containerRef} style={{ width:pw, height:ph, overflow:"hidden", position:"relative", borderRadius:8, border:"2px solid rgba(255,255,255,0.35)", cursor:"grab", userSelect:"none", flexShrink:0, touchAction:"none" }}
        onMouseDown={onMouseDown} onMouseMove={onMouseMove} onMouseUp={onMouseUp} onMouseLeave={onMouseUp}
        onTouchStart={onTouchStart} onTouchMove={onTouchMove} onTouchEnd={() => { lastPinchDist.current = null; }}>
        <canvas ref={pvCanvasRef} style={{ display:"block", width:pw, height:ph }} />
      </div>
      <div style={{ fontSize:11, color:"rgba(255,255,255,0.4)" }}>Zoom: {Math.round(crop.zoom * 100)} %</div>
      <div style={{ display:"flex", gap:12 }}>
        <button onClick={onCancel}      style={{ ...mkBtn(false, UI, DARK), padding:"10px 28px", fontSize:13 }}>Zrušit</button>
        <button onClick={handleConfirm} style={{ ...mkBtn(true,  UI, DARK), padding:"10px 28px", fontSize:13 }}>Potvrdit výřez</button>
      </div>
    </div>
  );
}

// ── App ───────────────────────────────────────────────────────────────────────
export default function App() {
  const [st, dispatch]                  = useReducer(reducer, null, initialState);
  const [confirmReset, setConfirmReset] = useState(false);
  const [isMobile, setIsMobile]         = useState(false);
  const [cropOpen, setCropOpen]         = useState(false);
  const dark = useDarkMode();
  const t    = dark ? DARK : LIGHT;

  const canvasRef     = useRef(null);
  const imgRef        = useRef(null);
  const logoCanvasRef = useRef(null);

  useEffect(() => {
    document.documentElement.style.margin = "0"; document.documentElement.style.padding = "0"; document.documentElement.style.background = t.bgMain;
    document.body.style.margin = "0"; document.body.style.padding = "0"; document.body.style.background = t.bgMain;
  }, [t.bgMain]);

  useEffect(() => {
    const check = () => setIsMobile(window.innerWidth < 768);
    check(); window.addEventListener("resize", check);
    return () => window.removeEventListener("resize", check);
  }, []);

  useEffect(() => {
    if (document.querySelector('link[href*="googleapis.com/css2?family=Inter"]')) return;
    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = "https://fonts.googleapis.com/css2?family=Inter:wght@400;700&family=Barlow:wght@400;700&family=Work+Sans:wght@400;600;700&display=swap";
    document.head.appendChild(link);
  }, []);

  const effectiveBgMode = st.bgMode === "custom" ? (st.customSub === "image" ? "image" : "color") : st.bgMode;

  const buildOpts = useCallback((overrides = {}) => ({
    bgMode: effectiveBgMode, bgColor: st.bgColor, bgImage: imgRef.current,
    overlayOpacity: st.overlayOpacity, headline: st.headline, subtext: st.showPerex ? st.subtext : "",
    supertitle: st.supertitle, textColor: st.textColor, fontFamily: st.fontFamily,
    fontScale: st.fontScale, textAlign: st.textAlign, textPos: st.textPos,
    logoVariant: st.logoVariant, richVariant: st.richVariant,
    richPhotoPos: st.richPhotoPos, richPanelColor: st.richPanelColor,
    cropRect: st.cropRect, photoCredit: st.photoCredit, creditColor: st.creditColor,
    zenaOverlay: st.zenaOverlay, zenaOverlayOpacity: st.zenaOverlayOpacity,
    ekonomOverlayOpacity: st.ekonomOverlayOpacity,
    ...overrides,
  }), [st, effectiveBgMode]);

  const previewMax = isMobile ? PREVIEW_MAX_MOBILE : PREVIEW_MAX_DESKTOP;

  const redraw = useCallback(() => {
    const canvas = canvasRef.current; if (!canvas) return;
    renderToCanvas(canvas, st.fmt, buildOpts(), previewMax);
  }, [st.fmt, buildOpts, previewMax]);

  const drawSidebarLogo = useCallback(() => {
    const c = logoCanvasRef.current; if (!c) return;
    const dpr = Math.min(window.devicePixelRatio || 1, MAX_DPR), size = 28;
    c.width = size * dpr; c.height = size * dpr;
    c.style.width = size + "px"; c.style.height = size + "px";
    const ctx = c.getContext("2d"); ctx.scale(dpr, dpr);
    drawLogoOnCanvas(ctx, size/2, size/2, size/2 - 1, "blue");
  }, []);

  useEffect(() => { redraw(); }, [redraw]);
  useEffect(() => { redraw(); drawSidebarLogo(); }, [isMobile]);
  useEffect(() => {
    document.fonts.load("bold 40px Inter").then(() => {
      document.fonts.load("bold 40px Barlow").then(() => {
        document.fonts.load("600 40px 'Work Sans'"); document.fonts.load("bold 40px 'Work Sans'");
        const MX = getMeasureCtx(); MX.font = "bold 40px Inter"; MX.measureText("A");
        const zi = _zenaLogoImg();
        if (zi.complete) { redraw(); drawSidebarLogo(); }
        else { zi.onload = () => { redraw(); drawSidebarLogo(); }; redraw(); drawSidebarLogo(); }
      });
    });
  }, []);

  const autoResize = e => { e.target.style.height = "auto"; e.target.style.height = e.target.scrollHeight + "px"; };
  const selectAll  = e => { const el = e.target; setTimeout(() => el.select(), 0); };

  const handleImageUpload = useCallback((e, targetMode = null) => {
    const file = e.target.files?.[0]; if (!file) return;
    const input = e.target;
    if (!ALLOWED_MIME.includes(file.type)) { alert("Nepodporovaný formát souboru.\nPovolené typy: JPEG, PNG, WebP, GIF."); input.value = ""; return; }
    if (file.size > MAX_FILE_BYTES) { alert("Soubor je příliš velký (max 20 MB)."); input.value = ""; return; }
    const reader = new FileReader();
    reader.onload = ev => {
      const dataUrl = ev.target.result;
      if (!ALLOWED_MIME.some(m => dataUrl.startsWith(`data:${m};base64,`))) { console.warn("Blocked suspicious data URL"); input.value = ""; return; }
      const img = new Image();
      img.onload = () => {
        imgRef.current = img;
        dispatch({ type:"SET", key:"cropRect", value:null });
        const canvas = canvasRef.current; if (!canvas) return;
        const PHOTO_TPLS = ["template3", "templateZena", "templateEkonomRich", "templateEkonomFoto"];
        let overrides;
        if (PHOTO_TPLS.includes(targetMode)) {
          overrides = { bgMode: targetMode, bgImage: img };
        } else {
          overrides = { bgMode:"image", bgImage:img };
          dispatch({ type:"SET", key:"bgMode", value:"custom" });
          dispatch({ type:"SET", key:"customSub", value:"image" });
        }
        renderToCanvas(canvas, st.fmt, { ...buildOpts(), ...overrides, cropRect:null }, previewMax);
      };
      img.onerror = () => { alert("Obrázek se nepodařilo načíst. Zkuste jiný soubor."); input.value = ""; };
      img.src = dataUrl;
    };
    reader.onerror = () => { alert("Chyba při čtení souboru. Zkuste to znovu."); input.value = ""; };
    reader.readAsDataURL(file);
  }, [st.fmt, buildOpts, previewMax]);

  const loadFromArticle = useCallback(async (rawUrl, isRetry = false) => {
    let target = rawUrl.trim();
    if (!/^https?:\/\//i.test(target)) target = "https://" + target;

    const controller = new AbortController();
    const timeoutId  = setTimeout(() => controller.abort(), 20000); // 20 s – článek + stažení fotky trvá typicky ~3 s

    try {
      const resp = await fetch(`/api/fetch-og?url=${encodeURIComponent(target)}`, { signal: controller.signal });
      clearTimeout(timeoutId);
      const data = await resp.json().catch(() => ({}));
      if (!resp.ok) return { ok:false, error: data.error || `Chyba ${resp.status}.` };

      dispatch({ type:"SET", key:"articleUrl", value: target });
      if (data.title) dispatch({ type:"SET", key:"headline", value: data.title });
      if (data.perex) dispatch({ type:"SET", key:"subtext",  value: data.perex });
      dispatch({ type:"SET", key:"photoCredit", value: data.credit || "" });

      const photoMode = st.bgMode === "template3" || st.bgMode === "templateZena" ||
                        st.bgMode === "templateEkonomRich" || st.bgMode === "templateEkonomFoto" ||
                        (st.bgMode === "custom" && st.customSub === "image");

      if (data.imageDataUrl) {
        await new Promise((resolve, reject) => {
          const img = new Image();
          img.onload = () => {
            imgRef.current = img;
            dispatch({ type:"SET", key:"cropRect", value:null });
            if (!photoMode) {
              dispatch({ type:"SET", key:"bgMode",       value:"template3" });
              dispatch({ type:"SET", key:"richPhotoPos", value:"top" });
              dispatch({ type:"SET", key:"richVariant",  value:"dark" });
              dispatch({ type:"SET", key:"logoVariant",  value:"blue" });
            }
            resolve();
          };
          img.onerror = () => reject(new Error("img"));
          img.src = data.imageDataUrl;
        }).catch(() => {});
      }
      return { ok:true, noImage: !data.imageDataUrl };
    } catch (e) {
      clearTimeout(timeoutId);
      // Jedno tiché automatické opakování – mobilní sítě občas zahodí první request (handoff wifi/LTE apod.).
      if (!isRetry && e && e.name !== "AbortError") {
        return loadFromArticle(rawUrl, true);
      }
      if (e && e.name === "AbortError") {
        return { ok:false, error:"Vypršel časový limit (20 s). Zkus to prosím znovu – server může být pomalý." };
      }
      return { ok:false, error:"Nepodařilo se připojit k serveru. Zkontroluj internetové připojení a zkus to znovu." };
    }
  }, [dispatch, st.bgMode, st.customSub]);

  const getCropDimensions = () => {
    const { w, h } = st.fmt;
    if (st.bgMode === "template3") return { cropW: w, cropH: Math.round(h * 0.55) };
    if (st.bgMode === "templateEkonomRich") return { cropW: w, cropH: Math.round(h * 0.60) };
    return { cropW: w, cropH: h };
  };

  const handleCropConfirm = cropRect => {
    dispatch({ type:"SET", key:"cropRect", value:cropRect });
    setCropOpen(false);
    const canvas = canvasRef.current;
    if (canvas) renderToCanvas(canvas, st.fmt, { ...buildOpts(), cropRect }, previewMax);
  };

  const doReset = () => { imgRef.current = null; dispatch({ type:"RESET" }); setConfirmReset(false); };

  const slugify = s => (s || "")
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "")
    .slice(0, 40) || "post";

  const exportName = f => {
    const tplName = TEMPLATE_NAMES[effectiveBgMode] || "vlastni";
    const date    = new Date().toISOString().slice(0, 10);
    return `${slugify(st.headline)}-${tplName}-${f.id}-${date}.png`;
  };

  const renderOffscreen = (f, cropForFmt) => {
    const off = document.createElement("canvas"); off.width = f.w; off.height = f.h;
    drawPost(off.getContext("2d"), f.w, f.h, buildOpts({ cropRect: cropForFmt }));
    return off;
  };

  const downloadCanvas = (off, name) => {
    const a = document.createElement("a");
    a.href = off.toDataURL("image/png");
    a.download = name;
    a.dispatchEvent(new MouseEvent("click", { bubbles:true, cancelable:true, view:window }));
  };

  const exportAs = () => {
    downloadCanvas(renderOffscreen(st.fmt, st.cropRect), exportName(st.fmt));
  };

  // Batch export všech formátů. Crop výřez platí jen pro aktuální formát
  // (je vázaný na jeho poměr stran); ostatní formáty dostanou automatický center-crop.
  const exportAllFormats = () => {
    FORMATS.forEach((f, idx) => {
      setTimeout(() => {
        const crop = f.id === st.fmt.id ? st.cropRect : null;
        downloadCanvas(renderOffscreen(f, crop), exportName(f));
      }, idx * 400);
    });
  };

  const copyToClipboard = async () => {
    if (!navigator.clipboard || typeof window.ClipboardItem === "undefined") return false;
    try {
      // Blob předáme líně přes Promise → clipboard.write se volá synchronně
      // v rámci kliknutí (zachová "user activation", funguje i v Safari).
      const blobPromise = new Promise((resolve, reject) => {
        const off = renderOffscreen(st.fmt, st.cropRect);
        off.toBlob(b => (b ? resolve(b) : reject(new Error("toBlob vrátil null"))), "image/png");
      });
      await navigator.clipboard.write([new ClipboardItem({ "image/png": blobPromise })]);
      return true;
    } catch (e1) {
      // Fallback: některé prohlížeče vyžadují už hotový blob
      try {
        const off  = renderOffscreen(st.fmt, st.cropRect);
        const blob = await new Promise(r => off.toBlob(r, "image/png"));
        if (!blob) return false;
        await navigator.clipboard.write([new ClipboardItem({ "image/png": blob })]);
        return true;
      } catch (e2) {
        console.warn("Kopírování do schránky selhalo:", e2);
        return false;
      }
    }
  };

  const shortCacheRef = useRef({});
  const shortenArticleUrl = useCallback(async () => {
    const url = st.articleUrl;
    if (!url) return { ok:false, error:"Není načtený článek." };
    if (shortCacheRef.current[url]) return { ok:true, shortlink: shortCacheRef.current[url] };
    try {
      const resp = await fetch(`/api/shorten?url=${encodeURIComponent(url)}`);
      const data = await resp.json().catch(() => ({}));
      if (!resp.ok || !data.shortlink) return { ok:false, error: data.error || `Chyba ${resp.status}.` };
      shortCacheRef.current[url] = data.shortlink;
      return { ok:true, shortlink: data.shortlink };
    } catch {
      return { ok:false, error:"Zkrácení se nepodařilo (síť)." };
    }
  }, [st.articleUrl]);

  const hasImage      = !!imgRef.current;
  const controlsProps = { st, dispatch, onImageUpload: handleImageUpload, onLoadArticle: loadFromArticle, autoResize, selectAll, t, mobile: isMobile };
  const previewProps  = { canvasRef, fmt: st.fmt, t, onImageUpload: handleImageUpload, onOpenCrop: () => setCropOpen(true), bgMode: st.bgMode, customSub: st.customSub, hasImage };
  const actionsProps  = { fmt: st.fmt, onReset: () => setConfirmReset(true), onNewPost: doReset, onExport: exportAs, onExportAll: exportAllFormats, onCopy: copyToClipboard, onShorten: shortenArticleUrl, articleUrl: st.articleUrl, perex: st.subtext, t, accent: st.bgMode === "templateZena" ? ZENA : (st.bgMode === "templateEkonomRich" || st.bgMode === "templateEkonomFoto") ? ekonomAccent(t) : UI };

  return (
    <div style={{ fontFamily:"Inter, system-ui, sans-serif", background:t.bgMain, minHeight:"100vh", color:t.textPrimary }}>

      {confirmReset && (
        <div style={{ position:"fixed", inset:0, background:"rgba(0,0,0,0.55)", display:"flex", alignItems:"center", justifyContent:"center", zIndex:1000 }}>
          <div style={{ background:t.bgSidebar, borderRadius:12, padding:"28px 32px", width:300, textAlign:"center", boxShadow:"0 8px 32px rgba(0,0,0,0.3)" }}>
            <div style={{ fontSize:16, fontWeight:700, color:t.textPrimary, marginBottom:8 }}>Začít znovu?</div>
            <div style={{ fontSize:13, color:t.textSecondary, marginBottom:24 }}>Skutečně chcete smazat dosavadní práci?</div>
            <div style={{ display:"flex", gap:10 }}>
              <button onClick={() => setConfirmReset(false)} style={{ ...mkBtn(false, UI, t), flex:1, padding:"9px 0", fontSize:13 }}>Ne</button>
              <button onClick={doReset}                      style={{ ...mkBtn(true,  UI, t), flex:1, padding:"9px 0", fontSize:13 }}>Ano</button>
            </div>
          </div>
        </div>
      )}

      {cropOpen && imgRef.current && (
        <CropModal img={imgRef.current} {...getCropDimensions()} initialCrop={st.cropRect} onConfirm={handleCropConfirm} onCancel={() => setCropOpen(false)} />
      )}

      {isMobile ? (
        <div style={{ display:"flex", flexDirection:"column" }}>
          <div style={{ background:t.bgSidebar, borderBottom:`1px solid ${t.border}`, padding:"14px 16px", position:"sticky", top:0, zIndex:10 }}>
            <AppHeader logoCanvasRef={logoCanvasRef} onLogoClick={() => setConfirmReset(true)} t={t} />
          </div>
          <div style={{ background:t.bgSidebar, padding:"16px 16px 8px", borderBottom:`1px solid ${t.border}` }}>
            <Controls {...controlsProps} />
          </div>
          <div style={{ background:t.bgMain, padding:"24px 16px 8px" }}>
            <Preview {...previewProps} />
          </div>
          <div style={{ position:"sticky", bottom:0, background:t.bgSidebar, borderTop:`1px solid ${t.borderLight}`, padding:"12px 16px" }}>
            <Actions {...actionsProps} mobile />
          </div>
        </div>
      ) : (
        <div style={{ display:"flex", height:"100vh", overflow:"hidden" }}>
          <div style={{ width:300, background:t.bgSidebar, borderRight:`1px solid ${t.border}`, display:"flex", flexDirection:"column", height:"100vh", flexShrink:0 }}>
            <div style={{ padding:"20px 18px 0" }}>
              <AppHeader logoCanvasRef={logoCanvasRef} onLogoClick={() => setConfirmReset(true)} t={t} />
            </div>
            <div style={{ flex:1, overflowY:"auto", padding:"16px 18px 8px" }}>
              <Controls {...controlsProps} />
            </div>
            <div style={{ padding:"0 18px 18px", background:t.bgSidebar, flexShrink:0 }}>
              <Actions {...actionsProps} />
            </div>
          </div>
          <div style={{ flex:1, display:"flex", alignItems:"center", justifyContent:"center", padding:32, overflowY:"auto" }}>
            <Preview {...previewProps} />
          </div>
        </div>
      )}
    </div>
  );
}
